import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Determinazione dei punti estremanti","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cg/cge.md","filePath":"lezioni/c_analisi/cg/cge.md"}`),a={name:`lezioni/c_analisi/cg/cge.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="determinazione-dei-punti-estremanti" tabindex="-1">Determinazione dei punti estremanti <a class="header-anchor" href="#determinazione-dei-punti-estremanti" aria-label="Permalink to “Determinazione dei punti estremanti”">​</a></h1><blockquote><p>La parola estremante è bruttissima ma è il termine tecnico: viene definito punto estremante un punto in cui possiamo avere un valore di massimo o di minimo o ove la derivata prima valga <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>, qualcuno vi comprende anche i punti dove il flesso è obliquo, ma io preferisco trattare questo caso a parte.</p></blockquote><h2 id="ricerca-dei-punti-di-massimo-minimo-e-flesso-orizzontale" tabindex="-1">Ricerca dei punti di massimo, minimo e flesso orizzontale <a class="header-anchor" href="#ricerca-dei-punti-di-massimo-minimo-e-flesso-orizzontale" aria-label="Permalink to “Ricerca dei punti di massimo, minimo e flesso orizzontale”">​</a></h2><p>Noi sappiamo che nei punti di massimo, di minimo e di flesso orizzontale la tangente è orizzontale cioè la derivata prima vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>.</p><p>Come si fa spesso in matematica ribaltiamo la frittata: se cerchiamo i punti dove la derivata prima vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> in questi punti ci sarà un massimo o un minimo o un flesso. Quindi la prima cosa da fare sarà calcolare la derivata prima, porla uguale a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> e risolvere l&#39;equazione per trovare i vari punti estremali. Poi potremo scegliere fra due metodi equivalenti per decidere se il punto è un massimo, un minimo od un flesso orizzontale:</p><ul><li>studio della derivata prima</li><li>metodo delle derivate successive</li></ul><p>Il primo metodo è pratico e veloce, il secondo è più teorico.</p><p>È preferibile usare il primo per funzioni che abbiano una derivata prima abbastanza semplice e conviene usare il secondo quando abbiamo funzioni con derivate facili da calcolare.</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};